// test_modules/batches/untested_abilities_batch27_test.rs::bp1009_debut_mill2_then_retrieve_member_from_waitroom
static void gen_bp1009_debut_mill2_then_retrieve_member_from_waitroom(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int me = test_id(&tg, "PL!N-bp1-009-R");
    int fodder = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_hand(&tg, me);
    test_add_to_hand(&tg, fodder);
    test_give_energy(&tg, 15);
    // 
    // // The retrieval target sits in the waitroom.
    int niji = test_id(&tg, "PL!N-bp3-004-R");
    test_add_to_discard(&tg, niji);
    // 
    // // Deck top: exactly the two cards that get milled.
    int m1 = test_id(&tg, "PL!-sd1-010-SD");
    int m2 = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_deck(&tg, m1);
    test_add_to_deck(&tg, m2);
    // 
    int waitroom_before = tg.state.p[0].discard.n;
    // 
    test_play_to_stage(&tg, me, 1);
    // // The retrieval step prompts "select member from waitroom" only AFTER
    // // the mill resolves — drain every pending choice in order.
    while (test_has_pending_choice(&tg)) rb_resume_with_choice(&tg.state, 0);
    rb_resume_with_choice(&tg.state, 0);
    // TODO: }
    // 
    CHECK(test_zone_has_id(&tg, 0, "hand", niji), "bp1009_debut_mill2_then_retrieve_member_from_waitroom");
    CHECK((!test_zone_has_id(&tg, 0, "discard", niji)), "bp1009_debut_mill2_then_retrieve_member_from_waitroom");
    CHECK(test_zone_has_id(&tg, 0, "discard", m1), "bp1009_debut_mill2_then_retrieve_member_from_waitroom");
    // TODO assert_eq (unresolved): assert_eq!( tg.state.player1.waitroom.cards.len(), waitroom_before + 2, "+2 milled-in, -1 retrieved-out; waitroom={:?}", tg.state.player1.waitroom.cards );
    // 
}

