// test_modules/abilities/moderate/eli_test.rs::eli_q79_vacated_area_can_play_new_member
static void gen_eli_q79_vacated_area_can_play_new_member(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int eli = test_id(&tg, "PL!-sd1-002-SD");
    int target_member = test_id(&tg, "PL!-sd1-001-SD");
    int new_member = test_id(&tg, "PL!-sd1-003-SD");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    // // Stage: 絢瀬絵里 at center (set directly, no need for play)
    tg.state.p[0].stage[0] = -1;
    tg.state.p[0].stage[1] = eli;
    tg.state.p[0].stage[2] = -1;
    // // Hand: filler (discard for hand count), new_member (for Q79 placement test)
    test_add_to_hand(&tg, filler);
    test_add_to_hand(&tg, new_member);
    // 
    // // Waitroom: ONLY the target member (avoids selection choice)
    // TODO: tg.add_to_discard(target_member);
    // 
    // // Enough energy for new_member's play cost (cost=13)
    test_give_energy(&tg, 15);
    // 
    // // Activate Eli's ability (self_cost → recover → vacates center)
    test_activate_ability(&tg, eli);
    // 
    // // The ability creates a selection choice because waitroom has 2 member cards
    // // (target_member + Eli after self_cost). Resolve the choice first.
    test_has_pending_choice(&tg);
    CHECK_EQ_STR(test_pending_choice_type(&tg), "SelectCard", "eli_q79_vacated_area_can_play_new_member");
    // // Find target_member's index in waitroom to recover it
    int idx = 0;
    rb_resume_with_choice(&tg.state, idx);
    // 
    // // After activation, center should be empty (self_cost removed Eli)
    CHECK_EQ(tg.state.p[0].stage[1], -1, "eli_q79_vacated_area_can_play_new_member");
    // 
    // // Q79: A new member CAN be placed in the vacated center area
    test_play_to_stage(&tg, new_member, 1);
    CHECK_EQ(tg.state.p[0].stage[1], new_member, "eli_q79_vacated_area_can_play_new_member");
    // 
}

