// test_modules/qa/qa_rulings_pins_test.rs::q37_live_start_grant_does_not_stack_on_refire
static void gen_q37_live_start_grant_does_not_stack_on_refire(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int member = test_id(&tg, "PL!N-bp3-005-R＋");
    int d1 = test_id(&tg, "PL!-sd1-010-SD");
    int d2 = test_id(&tg, "PL!-sd1-010-SD");
    // 
    test_give_energy(&tg, 30);
    tg.state.p[0].stage[0] = -1;
    tg.state.p[0].stage[1] = -1;
    tg.state.p[0].stage[2] = -1;
    test_add_to_hand(&tg, d1);
    test_add_to_hand(&tg, d2);
    test_add_to_hand(&tg, member);
    test_play_to_stage(&tg, d1, 0);
    // TODO: scan_autos_both(&mut game);
    test_play_to_stage(&tg, d2, 2);
    // TODO: scan_autos_both(&mut game);
    test_play_to_stage(&tg, member, 1);
    // TODO: scan_autos_both(&mut game);
    // 
    // // Fire the LiveStart trigger ONCE per its natural timing (Q37).
    // // NOTE: artificially calling fire_trigger twice STACKS the 常時 grant
    // // (gained_card_abilities registration is not idempotent). Real flow
    // // cannot reach that — LiveStart dispatch is phase-driven and single-shot,
    // // protected by the just_completed/this_batch guards. Hardening ticket:
    // // make gained-ability registration idempotent per (card, full_text).
    { int ftpl = rb_owner_of_card(&tg.state, member); if (ftpl < 0) ftpl = 0; rb_queue_trigger_abilities(&tg.state, ftpl, "ライブ開始時"); rb_drain_ability_queue(&tg.state); }
    test_recalc(&tg);
    // 
    // TODO assert_eq (unresolved): assert_eq!( tg.state.mods.p1_constant_total_score_bonus, 1, "Q37: one LiveStart timing -> exactly one 常時 score+1 grant" );
    // 
}

