    // TODO: guard += 1;
    rb_resume_with_choice(&tg.state, -1);
    // TODO: }
    // 
    int wait = 0;
    // TODO assert_eq (unresolved): assert_eq!( wait.len(), 1, "waitroom must be unchanged by the failed activation" );
    // TODO assert: assert!( wait.contains(&waitroom_member), "the waitroom member stays in the waitroom" );
    // TODO assert: assert!( !tg.state.player1.stage.stage.contains(&waitroom_member), "waitroom member must not be deployed by the failed activation" );
    // 
    // // Hand should still be empty because the ability cost failed
    CHECK_EQ(tg.state.p[0].hand.n, 0, "location_condition_negative_too_few_cards");
