// test_modules/abilities/simple/totemari_test.rs::tote_mari_q68_live_performance_discards_live_card
static void gen_tote_mari_q68_live_performance_discards_live_card(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int totemari = test_id(&tg, "PL!HS-bp2-014-N");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    int live = test_id(&tg, "LL-bp5-001-L");
    int opp_live = test_id(&tg, "LL-bp5-001-L");
    // 
    // // Fill decks
    // clear
    // TODO: for (int _i=0; _i<30; _i++) {
    test_add_to_deck(&tg, filler);
    // TODO: }
    // clear
    // TODO: for (int _i=0; _i<30; _i++) {
    test_add_to_deck(&tg, filler);
    // TODO: }
    // 
    // // P1 hand: totemari + live card
    test_add_to_hand(&tg, totemari);
    test_add_to_hand(&tg, live);
    // // P2 hand: live card
    test_add_to_hand(&tg, opp_live);
    // 
    test_give_energy(&tg, 4);
    // 
    test_play_to_stage(&tg, totemari, 1);
    while (test_has_pending_choice(&tg)) rb_resume_with_choice(&tg.state, 0);
    rb_resume_with_choice(&tg.state, -1);
    // TODO: }
    // 
    // // Advance to LiveCardSetFirstAttacker (P1's turn to set live cards).
    // // Each pass() advances ONE phase without settle: Main→Active→Energy→Draw→Main→LiveCardSetFirstAttacker
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    // 
    // // P1 live card set: set the live card (cannot_live should NOT block this)
    test_set_live_card(&tg, 0, live);
    CHECK(test_zone_has_id(&tg, 0, "live", live), "tote_mari_q68_live_performance_discards_live_card");
    // 
    // // Pass to LiveCardSetSecondAttacker (P2's turn)
    rb_advance_phase(&tg.state);
    // 
    // // P2 can also set a live card
    test_set_live_card(&tg, 0, opp_live);
    CHECK(test_zone_has_id(&tg, 1, "live", opp_live), "tote_mari_q68_live_performance_discards_live_card");
    // 
    // // Pass to performance phase and execute P1's performance
    // // First pass: LiveCardSetSecondAttacker → FirstAttackerPerformance (sets phase)
    // // Second pass: FirstAttackerPerformance → execute_performance_phase → SecondAttackerPerformance
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    // 
    // // Performance happens — cannot_live P1's live card should be discarded
    // // P1 is first attacker, so P1's performance resolves first
    // // After P1's performance, live card should go to waitroom
    // 
    // // P1's live card should have been discarded during performance due to cannot_live
    CHECK((!test_zone_has_id(&tg, 0, "live", live)), "tote_mari_q68_live_performance_discards_live_card");
    CHECK(test_zone_has_id(&tg, 0, "discard", live), "tote_mari_q68_live_performance_discards_live_card");
    // 
    // // P2's live card should still be present (opponent unaffected by cannot_live)
    // // P2 performs second
    CHECK(test_zone_has_id(&tg, 1, "live", opp_live), "tote_mari_q68_live_performance_discards_live_card");
    // 
    // // Cheer count should be 0 for P1 (no yell occurs with cannot_live)
    // TODO assert_eq (unresolved): assert_eq!( tg.state.player1_cheer_blade_heart_count, 0, "P1 cheer count is 0 (cannot_live)" );
    // 
}

