// test_modules/jidou/moderate/chisato_jidou_move_analysis_test.rs::third_member_position_change_no_energy_for_chisato
static void gen_third_member_position_change_no_energy_for_chisato(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int chisato = test_id(&tg, "PL!SP-bp2-003-R");
    int kinako = test_id(&tg, "PL!SP-bp5-006-R");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    test_add_to_hand(&tg, kinako);
    test_give_energy(&tg, 20);
    // TODO: for (int _i=0; _i<10; _i++) {
    test_add_to_deck_pl(&tg, 0, test_id(&tg, "LL-E-001-SD"));
    // TODO: }
    // TODO: for (int _i=0; _i<20; _i++) {
    test_add_to_deck(&tg, filler);
    // TODO: }
    // 
    // // Place Chisato on Center, filler on Right
    tg.state.p[0].stage[0] = -1;
    tg.state.p[0].stage[1] = chisato;
    tg.state.p[0].stage[2] = filler;
    // 
    // // Play Kinako to Left
    test_play_to_stage(&tg, kinako, 0);
    // 
    // // Playing Kinako triggers TAS → Chisato's auto queued.
    // // Observed: no prompt surfaces here — the queued auto resolves later,
    // // during Kinako's own activation flow.
    test_has_pending_choice(&tg);
    // 
    // // Now activate Kinako's kidou (position change)
    test_activate_ability(&tg, kinako);
    // 
    // // Should have a position destination choice
    test_has_pending_choice(&tg);
    // 
    // // Select Right as destination (swap Kinako with filler)
    // // inlined helper select_position_option
    // 
    // 
    // // After the swap, TAS scans and may queue Chisato's auto again.
    test_drain_auto_choices(&tg);
    // 
    // // Verify: Kinako is now on Right, filler is on Left
    CHECK_EQ(tg.state.p[0].stage[2], kinako, "third_member_position_change_no_energy_for_chisato");
    CHECK_EQ(tg.state.p[0].stage[0], filler, "third_member_position_change_no_energy_for_chisato");
    // // Chisato still on Center
    CHECK_EQ(tg.state.p[0].stage[1], chisato, "third_member_position_change_no_energy_for_chisato");
    // 
    // // KEY: Chisato did NOT move → no energy gain
    int energy_before = 20;
    CHECK_EQ(tg.state.p[0].energy.n, energy_before, "third_member_position_change_no_energy_for_chisato");
    // 
}

