// test_modules/batches/untested_abilities_batch23_test.rs::pb1014_baton_over_own_name_draws_two_discards_one
static void gen_pb1014_baton_over_own_name_draws_two_discards_one(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int r = 0; // auto-fix missing decl
    // 
    // // An older 中須かすみ copy occupies the left area.
    int old_me = test_id(&tg, "PL!N-pb1-014-R");
    tg.state.p[0].stage[0] = old_me;
    // 
    // // The fresh copy comes from hand and replaces her.
    int me = test_id(&tg, "PL!N-pb1-014-R");
    test_add_to_hand(&tg, me);
    test_give_energy(&tg, 20);
    // 
    // // Deck: two known draws on top.
    int d1 = test_id(&tg, "PL!-sd1-010-SD");
    int d2 = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_deck(&tg, d1);
    test_add_to_deck(&tg, d2);
    // TODO: while tg.state.player1.main_deck.cards.len() < 40 {
    int f = test_id(&tg, "PL!-sd1-010-SD");
    test_add_to_deck(&tg, f);
    // TODO: }
    // 
    test_play_to_stage(&tg, me, 0);
    // 
    // // Draw 2 landed...
    CHECK(test_zone_has_id(&tg, 0, "hand", d1), "pb1014_baton_over_own_name_draws_two_discards_one");
    // // ...then the hand-discard cost/effect step asks which card to bin.
    test_has_pending_choice(&tg);
    CHECK_EQ_STR(test_pending_choice_type(&tg), "SelectCard", "pb1014_baton_over_own_name_draws_two_discards_one");
    rb_resume_with_choice(&tg.state, 0);
    // 
    CHECK(test_zone_has_id(&tg, 0, "discard", old_me), "pb1014_baton_over_own_name_draws_two_discards_one");
    CHECK_EQ(tg.state.p[0].hand.n, 1, "pb1014_baton_over_own_name_draws_two_discards_one");
    CHECK((!tg.state.p[0].discard.n == 0), "pb1014_baton_over_own_name_draws_two_discards_one");
    // 
}

