// test_modules/abilities/moderate/butterfly_wing_suppress_test.rs::butterfly_wing_q260_suppressed_not_resolved
static void gen_butterfly_wing_q260_suppressed_not_resolved(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int butterfly = test_id(&tg, "PL!SP-pb2-046-L");
    int mei_r = test_id(&tg, "PL!SP-pb1-007-R");
    int mei_p = test_id(&tg, "PL!SP-pb1-007-P＋");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    // // Put 2 Meis (both have live_start) + 1 filler on stage
    test_add_to_stage(&tg, 1, filler);
    test_add_to_stage(&tg, 1, mei_p);
    test_add_to_stage(&tg, 1, mei_r);
    // 
    // // inlined helper setup_p1_deck
    // 
    // // inlined helper advance_to_live_card_set_p1
    // 
    test_add_to_hand(&tg, butterfly);
    test_set_live_card(&tg, 0, butterfly);
    // 
    // // Advance to live_start phase
    // // inlined helper advance_to_live_start
    // 
    // 
    // // Q260: Suppressed LiveStart abilities are NOT queued → NOT resolved
    // TODO assert_eq (unresolved): assert_eq!( tg.state.ability_queue.len(), 0, "Q260: Suppressed LiveStart abilities should NOT be in the queue (length 0)" );
    // 
    // // Drain any pending choices (should be none — LiveStart fully suppressed)
    while (test_has_pending_choice(&tg)) rb_resume_with_choice(&tg.state, 0);
    rb_resume_with_choice(&tg.state, -1);
    // TODO: }
    // 
    rb_advance_phase(&tg.state);
    while (test_has_pending_choice(&tg)) rb_resume_with_choice(&tg.state, 0);
    rb_resume_with_choice(&tg.state, -1);
    // TODO: }
    // 
    // // Cross-check: energy didn't change (confirms suppression)
    CHECK_EQ(tg.state.p[0].energy_active, 0, "butterfly_wing_q260_suppressed_not_resolved");
    // 
}

