// test_modules/abilities/moderate/kinako_test.rs::kinako_activate_discards_matching_card
static void gen_kinako_activate_discards_matching_card(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    // // 桜小路きな子 (activation ability on stage)
    int kinako = test_id(&tg, "PL!SP-bp2-006-P");
    // 
    // // A card with cost 4 (should be eligible for cost_limit=4)
    // // Using 鬼塚夏美 (PL!SP-bp2-009) - cost 3 card from スーパースター!! series
    int cost_card = test_id(&tg, "PL!SP-sd1-020-SD");
    // 
    // // A filler card with cost > 4 (should NOT be eligible)
    int high_cost_card = test_id(&tg, "PL!SP-sd1-012-SD");
    // 
    // // Give energy to play the cost-10 card
    test_give_energy(&tg, 10);
    // // Add cards to hand first, then play to stage
    test_add_to_hand(&tg, kinako);
    test_add_to_hand(&tg, cost_card);
    test_add_to_hand(&tg, high_cost_card);
    test_play_to_stage(&tg, kinako, 1);
    // 
    // // Activate ability #1 (起動 ability)
    // // The engine should filter hand cards by cost_limit=4
    // // Only cost_card (cost=2) should be selectable
    // TODO action: TurnEngine::execute_main_phase_action( &mut tg.state, &ActionType::UseAbility, Some(kinako), None, None, None, ).expect("activate_ability failed");
    // 
    // // Should have a pending choice to select the cost card.
    // // Observed: SelectCard zone=hand count=1 (cost_limit filter applied).
    test_has_pending_choice(&tg);
    CHECK_EQ_STR(test_pending_choice_type(&tg), "SelectCard", "kinako_activate_discards_matching_card");
    // // Select the first index (cost_card which is at hand index 0)
    rb_resume_with_choice(&tg.state, 0);
    // 
    // // Verify cost_card was discarded from hand
    CHECK((!test_zone_has_id(&tg, 0, "hand", cost_card)), "kinako_activate_discards_matching_card");
    // 
    // // Verify cost_card is now in discard
    CHECK(test_zone_has_id(&tg, 0, "discard", cost_card), "kinako_activate_discards_matching_card");
    // 
    // // Verify high_cost_card is still in hand (not eligible by cost)
    CHECK(test_zone_has_id(&tg, 0, "hand", high_cost_card), "kinako_activate_discards_matching_card");
    // 
}

