// test_modules/abilities/simple/setsuna_test.rs::setsuna_q157_wait_energy_can_be_placed_under_member
static void gen_setsuna_q157_wait_energy_can_be_placed_under_member(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int setsuna = test_id(&tg, "PL!N-bp3-007-R");
    int target = test_id(&tg, "PL!N-PR-009-PR");
    // 
    tg.state.p[0].stage[1] = setsuna;
    test_add_to_hand(&tg, target);
    // 
    // // 2 active (for cost) + 1 wait (for placement)
    test_give_energy(&tg, 2);
    test_add_to_energy(&tg, 0, test_id(&tg, "LL-E-001-SD"));
    // 
    int total_before = tg.state.p[0].energy.n;
    int active_before = tg.state.p[0].energy_active;
    // 
    test_activate_ability(&tg, setsuna);
    // // The hand debut target is a single candidate (auto-resolves); the engine
    // // then prompts once: SelectCard zone=energy count=1 allow_skip=false
    // // ("Choose energy card(s) to place under member").
    test_has_pending_choice(&tg);
    CHECK_EQ_STR(test_pending_choice_type(&tg), "SelectCard", "setsuna_q157_wait_energy_can_be_placed_under_member");
    rb_resume_with_choice(&tg.state, 0);
    // 
    int total_after = tg.state.p[0].energy.n;
    int active_after = tg.state.p[0].energy_active;
    // 
    // TODO assert_eq (unresolved): assert_eq!( active_before - active_after, 2, "2 active consumed for cost" );
    // TODO assert_eq (unresolved): assert_eq!( total_before - total_after, 1, "1 wait card popped for placement" );
    // 
}

