// test_modules/jidou/complex/konata_bp4_test.rs::konata_bp4_deploy_blade_heart_member_waits
static void gen_konata_bp4_deploy_blade_heart_member_waits(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int konata = test_id(&tg, "PL!N-bp4-006-R");
    // // A 虹ヶ咲 member with cost ≤4 and blade heart
    int bh_member = test_id(&tg, "PL!N-sd1-006-SD");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    // // Kanata in hand to play
    test_add_to_hand(&tg, konata);
    test_add_to_hand(&tg, bh_member);
    // // inlined helper fill_decks
    // 
    test_give_energy(&tg, 13);
    // 
    // // Play Kanata to stage — triggers debut ability
    test_play_to_stage(&tg, konata, 1);
    // 
    // // Pay the optional cost (2E) - must be offered.
    test_has_pending_choice(&tg);
    rb_resume_with_choice(&tg.state, 1);
    // 
    // // Choose a position for the deployed member.
    test_has_pending_choice(&tg);
    rb_resume_with_choice(&tg.state, 0);
    int konata_waited = 0;
    CHECK(konata_waited, "konata_bp4_deploy_blade_heart_member_waits");
    // // The deployed member must actually be ON STAGE — otherwise the wait
    // // could come from a failed deploy path.
    // TODO assert: assert!( tg.state.player1.stage.stage.contains(&bh_member), "BH member was deployed to the stage" );
    // 
}

