// test_modules/jidou/moderate/stage_to_discard_ability_test.rs::stage_to_discard_ability_triggers_only_on_baton_touch
static void gen_stage_to_discard_ability_triggers_only_on_baton_touch(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int card = 0; // auto-fix missing decl
    // 
    int honoka = test_id(&tg, "PL!-PR-001-PR");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    int arriver = test_id(&tg, "PL!S-bp5-012-N");
    // 
    // // Give enough energy for all plays
    test_give_energy(&tg, 30);
    // 
    // // Fill deck
    int deck_card = test_id(&tg, "PL!-sd1-010-SD");
    // TODO: for (int _i=0; _i<30; _i++) {
    test_add_to_deck(&tg, deck_card);
    // TODO: }
    // 
    // // ---- Step 1: Play Honoka to LeftSide (debut, empty area) ----
    test_add_to_hand(&tg, honoka);
    tg.state.p[0].stage[0] = -1;
    tg.state.p[0].stage[1] = -1;
    tg.state.p[0].stage[2] = -1;
    test_play_to_stage(&tg, honoka, 0);
    // 
    // // Should NOT trigger: card is on stage, not in discard
    test_has_pending_choice(&tg);
    // 
    // // ---- Step 2: Play filler to Center (debut, empty area) ----
    test_add_to_hand(&tg, filler);
    test_play_to_stage(&tg, filler, 1);
    // 
    // // Should NOT trigger
    test_has_pending_choice(&tg);
    // 
    // // ---- Step 3: Directly clear area lock to allow baton touch ----
    // TODO: tg.state.player1.deployed_this_turn.clear();
    // 
    // // ---- Step 4: Baton touch - play arriver to LeftSide (Honoka's area) ----
    test_add_to_hand(&tg, arriver);
    test_play_to_stage(&tg, arriver, 0);
    // 
    // // Honoka was replaced from stage to waitroom → her auto ability fires.
    // // The ability offers to activate 1 member. Since neither the filler nor
    // // the arriver are in wait state, there's nothing to activate — the
    // // option is NOT offered (unpayable cost).
    // // Use select_indices to confirm no pending choice exists.
    test_has_pending_choice(&tg);
    // 
    // // Verify Honoka is in waitroom
    CHECK(test_zone_has_id(&tg, 0, "discard", honoka), "stage_to_discard_ability_triggers_only_on_baton_touch");
    // 
}

