// test_modules/abilities/complex/aurora_flower_identity_test.rs::aoku_haruka_live_start_scores_with_aurora_in_discard
static void gen_aoku_haruka_live_start_scores_with_aurora_in_discard(void){
    // 
    // // Full integration test: PL!HS-bp2-022-L (アオクハルカ) live start ability:
    // //   "自分の控え室に『スリーズブーケ』のライブカードが3枚以上ある場合、
    // //    このカードのスコアを＋１する。"
    // //
    // // Setup: 2 static スリーズブーケ live cards + AURORA FLOWER (whose set_card_identity
    // // makes it a 3rd スリーズブーケ live card) in the discard. Without the fix,
    // // AURORA FLOWER wouldn't count and the condition would fail (count = 2 < 3).
    // // With the fix, count = 3, condition passes, +1 score modifier applies.
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int aoku = test_id(&tg, "PL!HS-bp2-022-L");
    int aurora = test_id(&tg, "PL!HS-bp5-018-L");
    int holiday = test_id(&tg, "PL!HS-bp1-021-L");
    int kagayaku = test_id(&tg, "PL!HS-bp2-021-L");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    test_add_to_hand(&tg, aoku);
    test_add_to_hand(&tg, filler);
    // TODO: for (int _i=0; _i<40; _i++) {
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    // TODO: }
    // 
    test_add_to_discard(&tg, aurora);
    test_add_to_discard(&tg, holiday);
    test_add_to_discard(&tg, kagayaku);
    test_give_energy(&tg, 10);
    // 
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    CHECK(strstr(rb_phase_name(tg.state.phase), "LiveCardSet") != NULL, "aoku_haruka_live_start_scores_with_aurora_in_discard");
    test_set_live_card(&tg, 0, aoku);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    while (test_has_pending_choice(&tg)) rb_resume_with_choice(&tg.state, 0);
    rb_resume_with_choice(&tg.state, 0);
    // TODO: }
    // 
    int score_mod = rb_mods_get_score(&tg.state.mods, aoku);
    CHECK_EQ(score_mod, 1, "aoku_haruka_live_start_scores_with_aurora_in_discard");
    // 
}

