static void gen_hazuki_activates_kidou_copied_from_under(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int hazuki = test_id(&tg, "PL!SP-pb2-005-R");
    // // PL!SP-sd1-006-SD (若菜四季): 起動: move self stage→waitroom → return live from discard
    int liella_with_kidou = test_id(&tg, "PL!SP-sd1-006-SD");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    int live = test_id(&tg, "PL!-sd1-020-SD");
    // 
    tg.state.p[0].stage[1] = hazuki;
    // TODO: tg.state.player1.stage.under_cards[1].push(liella_with_kidou);
    test_add_to_hand(&tg, filler);
    test_add_to_discard(&tg, live);
    // // inlined helper fill_decks
    // 
    test_give_energy(&tg, 5);
    // 
    // // Force recalculate_constants so ab#1 copies the kidou ability
    test_recalc(&tg);
    // 
    // // gained_card_abilities should now have the copied Ability struct
    // TODO assert: assert!( tg.state.gained_card_abilities.contains_key(&hazuki), "Hazuki should have gained card abilities" );
    int gained_list = 0;
    // TODO assert: assert!( gained_list .iter() .any(|a| a.triggers.as_ref().is_some_and(|t| &**t == "起動")), "Copied ability should have 起動 trigger" );
    // 
    // // Now activate the copied 起動 ability — still p1's main phase
    test_activate_ability(&tg, hazuki);
    // 
    // // The 起動 ability (from 若菜四季): self-stage→waitroom cost (auto via self_cost) +
    // // return 1 live from discard (auto-selects when exactly 1 live in discard)
    // // No pending choices expected since both steps auto-resolve.
    while (test_has_pending_choice(&tg)) rb_resume_with_choice(&tg.state, 0);
    rb_resume_with_choice(&tg.state, -1);
    // TODO: }
    // 
    CHECK(test_zone_has_id(&tg, 0, "discard", hazuki), "hazuki_activates_kidou_copied_from_under");
    CHECK(test_zone_has_id(&tg, 0, "hand", live), "hazuki_activates_kidou_copied_from_under");
    // 
}

