// test_modules/abilities/simple/fuyumari_test.rs::fuyumari_q63_effect_debut_no_cost_payment
static void gen_fuyumari_q63_effect_debut_no_cost_payment(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int fuyumari = test_id(&tg, "PL!SP-pb1-011-R");
    int liella_member = test_id(&tg, "PL!SP-sd1-006-SD");
    // 
    test_add_to_hand(&tg, fuyumari);
    tg.state.p[0].stage[0] = liella_member;
    test_give_energy(&tg, 13);
    // 
    tg.state.p[0].stage[1] = -1;
    test_play_to_stage(&tg, fuyumari, 1);
    // 
    // // Observed chain: the ability opens with a pay/skip gate
    // // (SelectTarget pay_optional_cost); answering card_indices [0] resolves
    // // to skip_optional_cost, so this test exercises the SKIP path (no swap,
    // // no effect). The state assertions below hold trivially on that path.
    test_has_pending_choice(&tg);
    CHECK_EQ_STR(test_pending_choice_type(&tg), "SelectTarget", "fuyumari_q63_effect_debut_no_cost_payment");
    rb_resume_with_choice(&tg.state, 0);
    test_has_pending_choice(&tg);
    // 
    CHECK_EQ(tg.state.p[0].energy_active, 0, "fuyumari_q63_effect_debut_no_cost_payment");
    CHECK_EQ(tg.state.p[0].stage[0], liella_member, "fuyumari_q63_effect_debut_no_cost_payment");
    CHECK_EQ(tg.state.p[0].stage[1], fuyumari, "fuyumari_q63_effect_debut_no_cost_payment");
    // 
}

