// test_modules/abilities/simple/fuyumari_test.rs::fuyumari_edge_exclude_self_from_cost
static void gen_fuyumari_edge_exclude_self_from_cost(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int filler = 0; // auto-fix missing decl
    // 
    int fuyumari = test_id(&tg, "PL!SP-pb1-011-R");
    int liella_member = test_id(&tg, "PL!SP-sd1-006-SD");
    // 
    test_add_to_hand(&tg, fuyumari);
    tg.state.p[0].stage[1] = -1;
    tg.state.p[0].stage[2] = liella_member;
    test_give_energy(&tg, 13);
    // 
    test_play_to_stage(&tg, fuyumari, 1);
    // 
    // // The optional stage cost now ALWAYS opens with a pay/skip gate — that
    // // gate itself is not an exclusion failure. Exclusion is proven by what
    // // follows: with exclude_self honored, exactly ONE candidate remains
    // // (liella_member), so after accepting there is NO SelectCard prompt
    // // (single candidate auto-resolves). If the filter were broken, ふるまり
    // // would be offered too and a SelectCard would appear here.
    // TODO assert: assert!( // inlined helper answer_stage_cost_gate  "optional stage cost must present a pay/skip gate" );
    test_has_pending_choice(&tg);
    // 
    // // inlined helper drain_auto_prompts_fuyumari
    // 
    CHECK_EQ(tg.state.p[0].stage[2], liella_member, "fuyumari_edge_exclude_self_from_cost");
    CHECK_EQ(tg.state.p[0].stage[1], fuyumari, "fuyumari_edge_exclude_self_from_cost");
    CHECK((!test_zone_has_id(&tg, 0, "discard", fuyumari)), "fuyumari_edge_exclude_self_from_cost");
    // 
}

