    // // Only the one clean member is selectable; skip the "place more?" re-prompt.
    rb_resume_with_choice(&tg.state, 0);
    while (test_has_pending_choice(&tg)) rb_resume_with_choice(&tg.state, 0);
    // TODO match block: while tg.has_pending_choice() {
    // TODO: }
