    // TODO assert_eq (unresolved): assert_eq!( *game .state .player1 .main_deck .cards .last() .expect("deck bottom holds the placed card"), clean, "placed card sits at the deck BOTTOM (push end)" );
    CHECK((!test_zone_has_id(&tg, 0, "discard", clean)), "emma_bp7008_only_clean_members_place_and_pay_energy");
    CHECK(test_zone_has_id(&tg, 0, "discard", bladefill), "emma_bp7008_only_clean_members_place_and_pay_energy");
    CHECK_EQ(tg.state.p[0].energy_active, 2, "emma_bp7008_only_clean_members_place_and_pay_energy");
