// test_modules/abilities/complex/fuyumari_debut_test.rs::fuyumari_q118_opponent_picks_first_card
static void gen_fuyumari_q118_opponent_picks_first_card(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int fuyumari = test_id(&tg, "PL!SP-bp2-011-R");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    int live_a = test_id(&tg, "PL!-sd1-019-SD");
    int live_b = test_id(&tg, "PL!-sd1-020-SD");
    // 
    test_add_to_hand(&tg, fuyumari);
    test_add_to_hand(&tg, filler);
    // // Order in discard: live_a at index 0, live_b at index 1
    test_add_to_discard(&tg, live_a);
    test_add_to_discard(&tg, live_b);
    // 
    test_give_energy(&tg, 11);
    tg.state.p[0].stage[0] = -1;
    test_play_to_stage(&tg, fuyumari, 0);
    // 
    // // Step 1: Player selects 2 distinct live cards from discard (indices 0 and 1)
    test_has_pending_choice(&tg);
    // // First choice should be routed to self (no choice_player_id override or = p1)
    // TODO assert_eq (unresolved): assert_eq!( tg.state .ability_queue .current_entry() .as_ref() .and_then(|e| e.choice_player_id.as_deref()), Some("p1"), "First select choice should be routed to activator (self)" );
    // action result consumed: tg.try_select_indices(&[0, 1]).unwrap();
    // 
    // // Step 2: Opponent picks a card from the selected ones
    // // The opponent select choice has source "selected_cards" with the 2 cards.
    // // The choice presents indices 0 and 1 (live_a, live_b).
    // // Opponent picks index 0 (live_a).
    test_has_pending_choice(&tg);
    // TODO assert_eq (unresolved): assert_eq!( tg.state .ability_queue .current_entry() .as_ref() .and_then(|e| e.choice_player_id.as_deref()), Some("p2"), "Opponent-select choice should be routed to opponent" );
    // // Verify generated_actions returns non-empty for opponent's selected_cards choice
    int actions = 0;
    // TODO assert: assert!( actions.len() >= 2, "Opponent should see at least 2 action options (got {})", actions.len() );
    rb_resume_with_choice(&tg.state, 0);
    // 
    // // Step 3: Opponent's chosen card (live_a, index 0 of selected_cards) goes to hand
    CHECK(test_zone_has_id(&tg, 0, "hand", live_a), "fuyumari_q118_opponent_picks_first_card");
    CHECK((!test_zone_has_id(&tg, 0, "discard", live_a)), "fuyumari_q118_opponent_picks_first_card");
    CHECK(test_zone_has_id(&tg, 0, "discard", live_b), "fuyumari_q118_opponent_picks_first_card");
    CHECK((!test_zone_has_id(&tg, 1, "hand", live_a)), "fuyumari_q118_opponent_picks_first_card");
    // 
}

