// test_modules/jidou/complex/maki_pb1_test.rs::maki_debut_pay_cost_opponent_waits_one
static void gen_maki_debut_pay_cost_opponent_waits_one(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int maki = test_id(&tg, "PL!-pb1-015-R");
    int p2_a = test_id(&tg, "PL!-pb1-011-R");
    int p2_b = test_id(&tg, "PL!-pb1-009-R");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    test_add_to_hand(&tg, maki);
    test_add_to_hand(&tg, filler);
    tg.state.p[1].stage[0] = p2_a;
    tg.state.p[1].stage[1] = p2_b;
    tg.state.p[1].stage[2] = -1;
    test_give_energy(&tg, 11);
    // 
    test_play_to_stage(&tg, maki, 1);
    // 
    // // ab#1 is pre-filtered out (no state change yet). ab#0 auto-resolves.
    // 
    // // 1. Pay optional cost (card_id=1 → "pay_optional_cost")
    rb_resume_with_choice(&tg.state, 1);
    // 
    // // 2. Opponent choice: select which of their 2 members to wait
    rb_resume_with_choice(&tg.state, 0);
    // 
    // // 3. ab#1 triggers (state change detected) and auto-resolves
    while (test_has_pending_choice(&tg)) rb_resume_with_choice(&tg.state, 0);
    rb_resume_with_choice(&tg.state, -1);
    // TODO: }
    // 
    // // Maki should be waited (state change, not moved to waitroom)
    // TODO assert_eq (unresolved): assert_eq!( tg.state.mods.orientation_modifiers.get(&maki), Some(&CardOrientation::Wait), "Maki should be in wait state (cost paid)" );
    int waited = 0;
    // TODO: tg.state.mods.orientation_modifiers.get(&id) == Some(&CardOrientation::Wait)
    // TODO: }).count();
    CHECK_EQ(waited, 1, "maki_debut_pay_cost_opponent_waits_one");
    // 
}

