// test_modules/jidou/complex/maki_pb1_test.rs::maki_ab1_use_limit_once_per_turn
static void gen_maki_ab1_use_limit_once_per_turn(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int maki = test_id(&tg, "PL!-pb1-015-R");
    int p2_a = test_id(&tg, "PL!-pb1-009-R");
    int p2_b = test_id(&tg, "PL!-pb1-011-R");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    test_add_to_hand(&tg, maki);
    test_add_to_hand(&tg, filler);
    tg.state.p[1].stage[0] = p2_a;
    tg.state.p[1].stage[1] = p2_b;
    tg.state.p[1].stage[2] = -1;
    test_give_energy(&tg, 15);
    test_add_to_deck(&tg, test_id(&tg, "PL!-sd1-013-SD"));
    // 
    // // hand = [maki, filler] = 2
    test_play_to_stage(&tg, maki, 1);
    // 
    // // ab#1 pre-filtered out (no state change yet). ab#0 auto-resolves.
    rb_resume_with_choice(&tg.state, 1);
    int entry = rb_queue_current_entry(&tg.state);
    // TODO assert_eq (unresolved): assert_eq!( entry.as_ref().and_then(|e| e.choice_player_id.as_deref()), Some("p2"), "Wait-member choice must be routed to opponent (p2)" );
    rb_resume_with_choice(&tg.state, 0);
    while (test_has_pending_choice(&tg)) rb_resume_with_choice(&tg.state, 0);
    rb_resume_with_choice(&tg.state, -1);
    // TODO: }
    // // hand = [filler, drawn] = 2 (play -1, draw +1 = net 0)
    CHECK_EQ(tg.state.p[0].hand.n, 2, "maki_ab1_use_limit_once_per_turn");
    // 
    // // Verify use_limit was consumed for this copy's ab#1 (ability index 1)
    int key = 0;
    CHECK(tg.state.turn, "maki_ab1_use_limit_once_per_turn");
    // 
    // // Second opponent member (p2_b, cost 2 ≤ 4) is still active.
    // // We can't easily trigger another wait to test the block in one turn,
    // // but the use_limit key check above proves the mechanism works:
    // // - use_limit is tracked per (card_id, ability_index, turn_number)
    // // - Different copies of Maki have different card_ids → each can trigger once
    // // - The same copy can't trigger ab#1 a second time in the same turn
    // TODO assert_eq (unresolved): assert_eq!( tg.state.mods.orientation_modifiers.get(&p2_b), None, "p2_b should still be active (only p2_a was waited)" );
    // 
}

