    tg.state.p[0].stage[2] = right_low_waited;
    rb_mods_set_orientation(&tg.state.mods, right_low_waited, "wait");
    test_recalc(&tg);
    // TODO assert_eq (unresolved): assert_eq!(heart03(&game, sumire), 1, "center 11 > left 9 and waited right 4 -> heart");
