// test_modules/edge_cases/sp_bp2_004_comprehensive_edge_test.rs::sp_bp2_004_position_change_re_evaluates
static void gen_sp_bp2_004_position_change_re_evaluates(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int sumire = test_id(&tg, "PL!SP-bp2-004-R");
    int center = test_id(&tg, "PL!HS-PR-001-PR");
    int right_high = test_id(&tg, "PL!SP-pb1-001-R");
    tg.state.p[0].stage[0] = sumire;
    tg.state.p[0].stage[1] = center;
    tg.state.p[0].stage[2] = right_high;
    test_recalc(&tg);
    // TODO assert_eq (unresolved): assert_eq!(heart03(&game, sumire), 0, "initially center 10 < right 11 -> no heart");
    // // Simulate position change: swap right high with empty? Just move right high out
    tg.state.p[0].stage[2] = -1;
    // // Place that high elsewhere? Actually removal already tested; here test move left<->center
    tg.state.p[0].stage[0] = center;
    tg.state.p[0].stage[1] = sumire;
    tg.state.p[0].stage[2] = -1;
    test_recalc(&tg);
    // // Now center is sumire 9, left is 10 -> center 9 < left 10 -> no heart (sumire at center but left higher)
    // TODO assert_eq (unresolved): assert_eq!(heart03(&game, sumire), 0, "sumire at center 9 < left 10 -> no heart after swap");
    // // Move high left away, leaving only sumire at center
    tg.state.p[0].stage[0] = -1;
    tg.state.p[0].stage[1] = sumire;
    tg.state.p[0].stage[2] = -1;
    test_recalc(&tg);
    // TODO assert_eq (unresolved): assert_eq!(heart03(&game, sumire), 1, "only sumire at center -> gains");
    // 
}

