// test_modules/abilities/complex/deep_resonance_bp3_test.rs::deep_resonance_option_0_blade_gain_exact_modifier
static void gen_deep_resonance_option_0_blade_gain_exact_modifier(void){
    TestGame tg; test_game_new(&tg);
    // 
    // // inlined helper make_test_game
    // 
    int game = 0;
    int dr = test_id(&tg, "PL!S-bp3-024-L");
    int aq_center = test_id(&tg, "PL!S-pb1-001-R");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    test_add_to_live(&tg, dr);
    tg.state.p[0].stage[0] = filler;
    tg.state.p[0].stage[1] = aq_center;
    tg.state.p[0].stage[2] = filler;
    // // inlined helper fill_decks
    // 
    // 
    int blade_before = rb_mods_get_blade(&tg.state.mods, aq_center);
    // 
    // // inlined helper trigger_ability
    // 
    test_has_pending_choice(&tg);
    // 
    // // Step 1: SelectTarget → pick option 0 (blade gain)
    CHECK_EQ_STR(test_pending_choice_type(&tg), "SelectTarget", "deep_resonance_option_0_blade_gain_exact_modifier");
    rb_resume_with_choice(&tg.state, 0);
    // 
    // // Step 2: SelectCard → pick which member gets the blade.
    // // Indices map to stage: 0=Left, 1=Center, 2=Right.
    // // Pick Center (aq_center).
    CHECK_EQ_STR(test_pending_choice_type(&tg), "SelectCard", "deep_resonance_option_0_blade_gain_exact_modifier");
    rb_resume_with_choice(&tg.state, 1);
    // 
    int blade_after = rb_mods_get_blade(&tg.state.mods, aq_center);
    // TODO assert_eq (unresolved): assert_eq!( blade_after, blade_before + 2, "center card gets exactly +2 blade (was {}, now {})", blade_before, blade_after );
    // // The Left filler was not selected — must be unchanged
    CHECK_EQ(test_get_blade_modifier(&tg, filler), 0, "deep_resonance_option_0_blade_gain_exact_modifier");
    // 
}

