// test_modules/qa/qa_new_tests209.rs::q209_kasumi_discard_niji_live_recover_same
static void gen_q209_kasumi_discard_niji_live_recover_same(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int kasumi = test_id(&tg, "PL!N-bp5-014-N");
    int niji_live = test_id(&tg, "PL!N-sd1-025-SD");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    test_add_to_hand(&tg, kasumi);
    test_add_to_hand(&tg, niji_live);
    test_add_to_hand(&tg, filler);
    test_give_energy(&tg, 10);
    // 
    // // Play Kasumi to stage
    test_play_to_stage(&tg, kasumi, 1);
    // 
    // // Baselines BEFORE activation: the fixed-count pay_energy step is
    // // auto-paid synchronously inside the activation call.
    int energy_before = tg.state.p[0].energy_active;
    int hand_before = tg.state.p[0].hand.n;
    int waitroom_before = tg.state.p[0].discard.n;
    // 
    // // Activate ability
    // TODO action: TurnEngine::execute_main_phase_action( &mut tg.state, &ActionType::UseAbility, Some(kasumi), None, None, None, ).expect("activate");
    // 
    // // Cost 1+2 (pay 2E, discard 1) and the retrieval effect may interleave
    // // prompts in any order depending on how the engine chains sequential_cost.
    // // The fixed-count pay_energy step is AUTO-PAID during activation (no
    // // prompt); only choice-based steps (hand discard) prompt.
    // 
    test_has_pending_choice(&tg);
    rb_resume_with_choice(&tg.state, 0);
    // 
    // // Drain any residual prompts (defensive; retrieval auto-resolves).
    while (test_has_pending_choice(&tg)) rb_resume_with_choice(&tg.state, 0);
    rb_resume_with_choice(&tg.state, -1);
    // TODO: }
    // 
    // // Strict outcome:
    CHECK(test_zone_has_id(&tg, 0, "hand", niji_live), "q209_kasumi_discard_niji_live_recover_same");
    CHECK_EQ(tg.state.p[0].hand.n, hand_before, "q209_kasumi_discard_niji_live_recover_same");
    CHECK_EQ(tg.state.p[0].discard.n, waitroom_before, "q209_kasumi_discard_niji_live_recover_same");
    CHECK_EQ(tg.state.p[0].energy_active, energy_before - 2, "q209_kasumi_discard_niji_live_recover_same");
    // 
}

