    test_add_to_deck(&tg, filler);
    // TODO: }
    // TODO: }
    tg.state.p[0].stage[0] = kotori;
    tg.state.p[0].stage[1] = filler;
    tg.state.p[0].stage[2] = -1;
    test_add_to_hand(&tg, muse_card);
    test_add_to_discard(&tg, live);
    test_give_energy(&tg, 10);
    // TODO: tg.state.turn_number = 1;
    // 
    test_activate_ability(&tg, kotori);
    // 
    // // Cost: discard 1 from hand
    test_has_pending_choice(&tg);
    rb_resume_with_choice(&tg.state, 0);
    // 
    // // Primary effect: look at top 4, select 2 to hand
    test_has_pending_choice(&tg);
    // 
    int choice = 0;
    // TODO match block: let choice = tg.get_pending_choice();
