    rb_resume_with_choice(&tg.state, 0);
    rb_resume_with_choice(&tg.state, 1);
    test_has_pending_choice(&tg);
    // 
    // // 2 looked-at cards moved to hand, 2 discarded
    CHECK_EQ(tg.state.p[0].hand.n, 2, "kotori_discard_muse_look_and_select");
    CHECK(test_zone_has_id(&tg, 0, "discard", live), "kotori_discard_muse_look_and_select");
