    test_add_to_hand(&tg, live_card);
    test_add_to_hand(&tg, p2_card);
    test_give_energy(&tg, 1);
    // 
    // // inlined helper setup_yoshiko
    // 
    // 
    // // Opponent discards their only card
    rb_resume_with_choice(&tg.state, 0);
    // 
