    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    int hot_p1 = test_id(&tg, "PL!SP-bp5-027-L");
    int happy_p2 = test_id(&tg, "PL!S-bp6-022-L");
    test_add_to_live(&tg, hot_p1);
    test_add_to_live(&tg, happy_p2);
    // 
    // TODO: fill_decks(&mut game, filler);
    // TODO: fill_energy_deck(&mut game, 0, 1);
    // // inlined helper give_total_energy
