// test_modules/abilities/complex/live_success_rules_test.rs::live_fails_with_insufficient_hearts
static void gen_live_fails_with_insufficient_hearts(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int live = test_id(&tg, "PL!-sd1-019-SD");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    int member = test_id(&tg, "PL!S-sd1-003-SD");
    tg.state.p[0].stage[0] = member;
    tg.state.p[0].stage[1] = -1;
    tg.state.p[0].stage[2] = -1;
    test_add_to_hand(&tg, live);
    // TODO: for (int _i=0; _i<50; _i++) {
    test_add_to_deck(&tg, filler);
    // TODO: }
    // TODO: for (int _i=0; _i<20; _i++) {
    test_add_to_deck(&tg, filler);
    // TODO: }
    // // inlined helper advance_to_live_card_set_p1
    // 
    test_set_live_card(&tg, 0, live);
    // // inlined helper advance_to_live_start
    // 
    // TODO: tg.drain_choices_strict(&["SelectCard", "SelectAutoAbility"], &[]);
    // // inlined helper advance_to_live_victory
    // 
    // TODO: tg.drain_choices_strict(&["SelectCard", "SelectAutoAbility"], &[]);
    // // One more pass finalizes victory determination (winner placement).
    rb_advance_phase(&tg.state);
    // 
    // // Q35: the failed live card must end in the WAITROOM — never the
    // // success zone. A bare "!has_pending_choice()" cannot distinguish this
    // // from any other terminal state.
    CHECK(test_zone_has_id(&tg, 0, "discard", live), "live_fails_with_insufficient_hearts");
    CHECK(tg.state.p[0].success.n == 0, "live_fails_with_insufficient_hearts");
    // 
}

// test_modules/abilities/complex/live_success_rules_test.rs::both_players_live_score_compared
static void gen_both_players_live_score_compared(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int p1_live = test_id(&tg, "PL!-sd1-019-SD");
    int p2_live = test_id(&tg, "PL!-sd1-019-SD");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    int member = test_id(&tg, "PL!-sd1-001-SD");
    tg.state.p[0].stage[0] = member;
    tg.state.p[0].stage[1] = member;
    tg.state.p[0].stage[2] = member;
    tg.state.p[1].stage[0] = member;
    tg.state.p[1].stage[1] = member;
    tg.state.p[1].stage[2] = member;
    test_add_to_hand(&tg, p1_live);
    test_add_to_hand(&tg, p2_live);
    // TODO: for (int _i=0; _i<50; _i++) {
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    // TODO: }
    // // inlined helper advance_to_live_card_set_p1
    // 
    test_set_live_card(&tg, 0, p1_live);
    // // inlined helper advance_to_live_start
    // 
    // TODO: tg.drain_choices_strict(&["SelectCard", "SelectAutoAbility"], &[0]);
    // // inlined helper advance_to_live_victory
    // 
    // TODO: tg.drain_choices_strict(&["SelectCard", "SelectAutoAbility"], &[0]);
    // // One more pass to finalize LiveVictoryDetermination (move winner to success zone)
    rb_advance_phase(&tg.state);
    int p1_success = tg.state.p[0].success.n;
    int p2_success = tg.state.p[1].success.n;
    // // Exactly one player wins (identical live cards, same score → P1 wins as first attacker)
    CHECK_EQ(p1_success, 1, "both_players_live_score_compared");
    CHECK_EQ(p2_success, 0, "both_players_live_score_compared");
    // 
}

