    CHECK_EQ(tg.state.p[0].success.n, 1, "two_live_cards_choose_second");
    // TODO assert_eq (unresolved): assert_eq!( tg.state.player1.success_live_card_zone.cards[0], live_b, "Second live card (live_b) was chosen for success" );
