static void gen_liella_blade_2_gets_correct_modifier(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int opp_liella = 0; // auto-fix missing decl
    int self_liella = 0; // auto-fix missing decl
    // 
    int special = test_id(&tg, "PL!SP-bp4-025-L");
    int liella_blade2 = test_id(&tg, "PL!SP-PR-012-PR");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    tg.state.p[0].stage[0] = -1;
    tg.state.p[0].stage[1] = liella_blade2;
    tg.state.p[0].stage[2] = -1;
    test_add_to_hand(&tg, special);
    test_add_to_hand(&tg, filler);
    // // inlined helper fill_decks
    // 
    // 
    // // inlined helper advance_to_live_card_set_p1
    // 
    test_set_live_card(&tg, 0, special);
    // // inlined helper advance_to_live_start
    // 
    // 
    // // Two live-start autos are queued: the live card's set_blade_count and
    // // PR-012-PR's own optional discard. Resolve them in order, declining the
    // // discard so set_blade_count's result is visible.
    test_has_pending_choice(&tg);
    CHECK_EQ_STR(test_pending_choice_type(&tg), "SelectAutoAbility", "liella_blade_2_gets_correct_modifier");
    rb_resume_with_choice(&tg.state, 0);
    CHECK_EQ_STR(test_pending_choice_type(&tg), "SelectCard", "liella_blade_2_gets_correct_modifier");
    rb_resume_with_choice(&tg.state, -1);
    // 
    CHECK_EQ(test_get_blade_modifier(&tg, liella_blade2), 3, "liella_blade_2_gets_correct_modifier");
    // 
}

