// test_modules/abilities/complex/hinoshita_test.rs::hinoshita_q236_name_contains_all_matches
static void gen_hinoshita_q236_name_contains_all_matches(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int hino = test_id(&tg, "PL!HS-bp5-001-P");
    int reveal_live = test_id(&tg, "PL!HS-bp1-019-L");
    int target_live = test_id(&tg, "PL!HS-bp5-017-L");
    // 
    // // Stage: 日野下花帆 at center
    tg.state.p[0].stage[1] = hino;
    // 
    // // Hand: the live card to reveal
    test_add_to_hand(&tg, reveal_live);
    // 
    // // Waitroom: the live card to recover
    test_add_to_discard(&tg, target_live);
    // 
    // // Energy: 2 for activation cost
    test_give_energy(&tg, 2);
    int energy_before = tg.state.p[0].energy_active;
    // 
    test_activate_ability(&tg, hino);
    // 
    // // Exactly 1 live card in hand → auto-select (no choice for reveal).
    // // Exactly 1 matching card in waitroom → auto-select (no choice for recovery).
    // // So has_pending_choice() should be false.
    while (test_has_pending_choice(&tg)) rb_resume_with_choice(&tg.state, 0);
    rb_resume_with_choice(&tg.state, 0);
    // TODO: }
    // 
    // // Q236: Target should be in hand
    CHECK(test_zone_has_id(&tg, 0, "hand", target_live), "hinoshita_q236_name_contains_all_matches");
    // 
    // // Revealed card must stay in hand (公開する = reveal, NOT discard)
    CHECK(test_zone_has_id(&tg, 0, "hand", reveal_live), "hinoshita_q236_name_contains_all_matches");
    // 
    // // 2 energy consumed
    CHECK_EQ(tg.state.p[0].energy_active, energy_before - 2, "hinoshita_q236_name_contains_all_matches");
    // 
}

