// test_modules/abilities/moderate/b9_more_test.rs::kaguya_live_success_cheer_recover
static void gen_kaguya_live_success_cheer_recover(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int kaguya = test_id(&tg, "PL!-pb1-031-L");
    int member = test_id(&tg, "PL!-sd1-001-SD");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    int bladed_member = test_id(&tg, "PL!S-sd1-003-SD");
    // 
    // // Stage: bladed member for cheer + member with heart06 for live success requirement
    tg.state.p[0].stage[0] = bladed_member;
    tg.state.p[0].stage[1] = member;
    tg.state.p[0].stage[2] = -1;
    test_add_to_hand(&tg, kaguya);
    test_add_to_hand(&tg, filler);
    // 
    // // Deck: need exactly 1 filler before member because:
    // // - LiveCardSetFirstAttacker replacement draw consumes 1 card from P1's deck
    // // - Yell then draws from index 0 = member = first in revealed_cards
    // // (Odd trivia: the draw phase during the first 5 passes draws from P2, not P1)
    // clear
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, member);
    // TODO: for (int _i=0; _i<30; _i++) {
    test_add_to_deck(&tg, filler);
    // TODO: }
    // clear
    // TODO: for (int _i=0; _i<30; _i++) {
    test_add_to_deck(&tg, filler);
    // TODO: }
    // 
    // // Advance to live card set phase
    // TODO: for (int _i=0; _i<5; _i++) {
    rb_advance_phase(&tg.state);
    // TODO: }
    test_set_live_card(&tg, 0, kaguya);
    // 
    // // Advance through remaining phases to live performance
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    // 
    // // After live performance, cheer-revealed cards should be in revealed_cards
    // // If the member was cheer-revealed, the ability should add it to hand
    // // Handle all pending choices (cost + revealed_cards selection)
    while (test_has_pending_choice(&tg)) rb_resume_with_choice(&tg.state, 0);
    // // Select the first option whenever prompted
    rb_resume_with_choice(&tg.state, 0);
    // TODO: }
    // 
    // // Verify: the μ's member card was recovered to hand by the LiveSuccess ability
    CHECK(test_zone_has_id(&tg, 0, "hand", member), "kaguya_live_success_cheer_recover");
    // 
}

