// test_modules/integration/victory_road_test.rs::test_each_time_drains_between_live_starts_no_mix
static void gen_test_each_time_drains_between_live_starts_no_mix(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int idx = 0;
    // 
    int victory = test_id(&tg, "PL!N-bp5-030-L");
    int member_a = test_id(&tg, "PL!-bp3-012-N");
    int member_b = test_id(&tg, "PL!-bp3-011-N");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    // // Fill deck with filler cards to avoid unwantd triggers
    // clear
    // clear
    // TODO: for (int _i=0; _i<30; _i++) {
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    // TODO: }
    // 
    // // Place Victory Road (each_time LiveStart watcher) in live card zone
    test_add_to_live(&tg, victory);
    // 
    // // Place 2 members with LiveStart ability on stage
    tg.state.p[0].stage[0] = member_a;
    tg.state.p[0].stage[1] = member_b;
    tg.state.p[0].stage[2] = -1;
    // 
    test_add_to_hand(&tg, victory);
    test_add_to_hand(&tg, filler);
    // 
    // // Advance to the LiveStart phase (engine internally queues LS abilities)
    // // inlined helper advance_to_live_start
    // 
    test_set_live_card(&tg, 0, victory);
    // // inlined helper finish_live_setup
    // 
    // 
    // // At this point, trigger_live_start_abilities has queued [LS#1, LS#2].
    // // We call process_pending_auto_abilities directly to intercept choices.
    // 
    // // ── Step 1: Queue LiveStart abilities ──
    int p1_id = 0;
    // TODO: rabuka_engine::turn::TurnEngine::trigger_live_start_abilities(&mut tg.state, &p1_id);
    // TODO: rabuka_engine::turn::TurnEngine::trigger_live_start_abilities(&mut tg.state, &"player2");
    // 
    // // ── Step 2: Start processing ──
    // // process_pending_auto_abilities enters process_player_abilities,
    // // finds [LS#1, LS#2] → available > 1 → SelectAutoAbility choice
    rb_drain_ability_queue(&tg.state);
    // 
    // // Verify we got the expected choice: pick order among 2 LS abilities
    test_has_pending_choice(&tg);
    // TODO match block: assert!( tg.has_pending_choice(), "Expected SelectAutoAbility choice for LS order" );
    // 
    // // ── Step 3: Pick LS#1 (index 0) ──
    // // resume_with_choice internally calls process_pending_auto_abilities again
    // // which continues the loop. With the depth-first fix:
    // //   - LS#1 resolves → each_time queued at idx >= pre_len → drain loop forces it
    // //   - available=[LS#2] → auto-promote → LS#2 resolves → ET2 drain → done
    // // Without the fix:
    // //   - LS#1 resolves → each_time queued
    // //   - available=[LS#2, ET] → another SelectAutoAbility choice ← WRONG
    rb_resume_with_choice(&tg.state, 0);
    // 
    // // ── Step 4: Verify NO SelectAutoAbility appeared for LS#2 vs each_time ──
    // // If the fix works, the each_time was force-drained, and LS#2 auto-resolved.
    // // Observed chain: after picking LS#1, the pending choice is its own effect's
    // // SelectHeartColor ("Choose a heart color", options heart01/03/06). A
    // // second SelectAutoAbility here would mean the each_time was NOT
    // // force-drained and is mixed with LS#2 in the player's choice.
    test_has_pending_choice(&tg);
    CHECK_EQ_STR(test_pending_choice_type(&tg), "SelectHeartColor", "test_each_time_drains_between_live_starts_no_mix");
    // 
    // // ── Step 5: Drain any remaining choices ──
    while (test_has_pending_choice(&tg)) rb_resume_with_choice(&tg.state, 0);
    rb_resume_with_choice(&tg.state, -1);
    // TODO: }
    // 
    // // ── Step 6: Verify both members got All Heart from each_time triggers ──
    // TODO assert: assert!( // inlined helper has_all_heart  "member_a got all-heart (each_time should fire for every LS)" );
    // TODO assert: assert!( // inlined helper has_all_heart  "member_b got all-heart (each_time should fire for every LS)" );
    // 
}

