// test_modules/jidou/complex/cards_6_thru_13_test.rs::c8_q242_both_shuffle_and_retrieve_and_blade
static void gen_c8_q242_both_shuffle_and_retrieve_and_blade(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int c = test_id(&tg, "PL!HS-pb1-012-R");
    int m = test_id(&tg, "PL!-sd1-001-SD");
    int live = test_id(&tg, "PL!-sd1-019-SD");
    int f = test_id(&tg, "PL!-sd1-010-SD");
    tg.state.p[0].stage[0] = -1;
    tg.state.p[0].stage[1] = c;
    tg.state.p[0].stage[2] = -1;
    // 
    // // 10 member cards each in both players' discards = 20 total (hits threshold)
    // TODO: for (int _i=0; _i<10; _i++) {
    test_add_to_discard(&tg, m);
    test_add_to_discard(&tg, m);
    // TODO: }
    // // Live card in P1's discard for retrieval
    test_add_to_discard(&tg, live);
    int w1_before = tg.state.p[0].discard.n;
    // 
    // // inlined helper deck
    // 
    test_give_energy(&tg, 5);
    int blade_before = rb_mods_get_blade(&tg.state.mods, c);
    // 
    // // inlined helper trigger_momoo_debut
    // 
    // 
    // // Live card was retrieved from discard to hand
    CHECK(test_zone_has_id(&tg, 0, "hand", live), "c8_q242_both_shuffle_and_retrieve_and_blade");
    CHECK((!test_zone_has_id(&tg, 0, "discard", live)), "c8_q242_both_shuffle_and_retrieve_and_blade");
    // // P1's waitroom shrank (member cards shuffled under + live card retrieved)
    CHECK(tg.state.p[0].discard.n, "c8_q242_both_shuffle_and_retrieve_and_blade");
    // 
    // // Blade+2 gained
    int blade_after = rb_mods_get_blade(&tg.state.mods, c);
    CHECK_EQ(blade_after, blade_before + 2, "c8_q242_both_shuffle_and_retrieve_and_blade");
    // 
}

