// test_modules/integration/parser_issues_e2e_test.rs::proof_cost_20plus_draws_card
static void gen_proof_cost_20plus_draws_card(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int proof = test_id(&tg, "PL!HS-bp6-029-L");
    // // Use abilityless 蓮ノ空 members (no LiveStart to interfere):
    // //   PL!HS-bp1-016-PR cost=9, PL!HS-bp1-016-N cost=9, PL!HS-bp1-012-PR cost=4
    // //   Total: 9+9+4=22 >= 20
    int hs1 = test_id(&tg, "PL!HS-bp1-016-PR");
    int hs2 = test_id(&tg, "PL!HS-bp1-016-N");
    int hs3 = test_id(&tg, "PL!HS-bp1-012-PR");
    // // Use filler for remaining cards
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    tg.state.p[0].stage[0] = hs1;
    tg.state.p[0].stage[1] = hs2;
    tg.state.p[0].stage[2] = hs3;
    // clear
    // // Top 2 must be 蓮ノ空 cards (select_action has group_names filter)
    int top1 = test_id(&tg, "PL!HS-bp1-012-PR");
    int top2 = test_id(&tg, "PL!HS-bp1-012-N");
    test_add_to_deck(&tg, top1);
    test_add_to_deck(&tg, top2);
    // TODO: for (int _i=0; _i<10; _i++) {
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    // TODO: }
    // 
    test_add_to_hand(&tg, proof);
    // // inlined helper advance_to_live_card_set_p1
    // 
    test_set_live_card(&tg, 0, proof);
    // // inlined helper advance_to_live_start
    // 
    // 
    // // Only Proof's LiveStart fires (abilityless members have none).
    // // Proof's look-and-select creates a SelectCard choice → pick index 0.
    int hand_after_setup = tg.state.p[0].hand.n;
    while (test_has_pending_choice(&tg)) rb_resume_with_choice(&tg.state, 0);
    rb_resume_with_choice(&tg.state, 0);
    // TODO: }
    // 
    // // Total cost 9+9+4=22 >= 20 → look-and-select fires → draws 1 card
    int hand_after = tg.state.p[0].hand.n;
    // TODO assert_eq (unresolved): assert_eq!( hand_after, hand_after_setup + 1, "Proof: cost 22 >= 20 → should draw 1 card (hand {}=>{} )", hand_after_setup, hand_after );
    // TODO assert_eq (unresolved): assert_eq!( tg.state .mods .get_need_heart_modifier(proof, HeartColor::Heart00), 0, "Proof: cost 22 < 30 → no heart reduction" );
    // 
}

