    // // Self 蓮ノ空 total after +6: 16 > opponent 12 → condition met
    int heart05 = rb_mods_get_heart(&tg.state.mods, suzu, 5);
    // TODO assert_eq (unresolved): assert_eq!( heart05, 1, "17a: Suzu should gain heart05 (16>12), got {}", heart05 );
