// test_modules/abilities/complex/ability_engine_fixes_test.rs::chisato_003_rotation_full_stage
static void gen_chisato_003_rotation_full_stage(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int filler = 0; // auto-fix missing decl
    int keke = 0; // auto-fix missing decl
    int liella_bh = 0; // auto-fix missing decl
    // 
    int chisato = test_id(&tg, "PL!SP-pb1-003-R");
    // // Two other 5yncri5e! members (use N rarity for filler status but same unit)
    int member_a = test_id(&tg, "PL!SP-pb1-014-N");
    int member_b = test_id(&tg, "PL!SP-pb1-019-N");
    // 
    test_add_to_hand(&tg, chisato);
    test_give_energy(&tg, 9);
    // 
    // // Set up: 2 existing 5yncri5e! members at Left and Center
    tg.state.p[0].stage[0] = member_a;
    tg.state.p[0].stage[1] = member_b;
    tg.state.p[0].stage[2] = -1;
    // // We'll play chisato to Right
    // 
    test_play_to_stage(&tg, chisato, 2);
    // 
    // // Debut trigger fires, condition check passes (all are 5yncri5e!)
    // // Rotation should have happened automatically:
    // // Before: [member_a, member_b, chisato]
    // // After:  [member_b, chisato, member_a]
    // //   left(0)←center(1): member_b←old member_b (stays... wait)
    // //   Actually rotation: center→left, left→right, right→center
    // //   center(1)→left(0): member_b moves to left
    // //   left(0)→right(2): member_a moves to right
    // //   right(2)→center(1): chisato moves to center
    // //   Result: [member_b, chisato, member_a]
    // 
    // TODO assert: assert!( tg.state.ability_queue.is_waiting_for_choice().is_none(), "Rotation should complete without choices (predetermined destinations)" );
    // 
    CHECK_EQ(tg.state.p[0].stage[0], member_b, "chisato_003_rotation_full_stage");
    CHECK_EQ(tg.state.p[0].stage[1], chisato, "chisato_003_rotation_full_stage");
    CHECK_EQ(tg.state.p[0].stage[2], member_a, "chisato_003_rotation_full_stage");
    // 
}

