// test_modules/abilities/complex/ability_engine_fixes_test.rs::kanon_unless_pay_pay_avoids_discard
static void gen_kanon_unless_pay_pay_avoids_discard(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int kanon = test_id(&tg, "PL!SP-pb1-001-R");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    int live_card = test_id(&tg, "PL!-sd1-019-SD");
    // 
    // // Kanon is a member — play her to stage for live_start ability
    test_add_to_hand(&tg, kanon);
    test_add_to_hand(&tg, filler);
    test_add_to_hand(&tg, filler);
    test_give_energy(&tg, 13);
    // 
    // // Seed deck for yell + draws
    // TODO: for (int _i=0; _i<10; _i++) {
    test_add_to_deck(&tg, filler);
    test_add_to_deck(&tg, filler);
    // TODO: }
    // 
    test_add_to_hand(&tg, live_card);
    // // Play Kanon to Center, then set live card
    test_play_to_stage(&tg, kanon, 1);
    // 
    // // inlined helper advance_to_live_card_set_p1_kanon
    // 
    test_set_live_card(&tg, 0, live_card);
    // // Record hand AFTER live card is set (removed from hand)
    int hand_before = tg.state.p[0].hand.n;
    // // Passing from LiveCardSetFirstAttacker draws 1 card per live card placed
    // // inlined helper advance_to_live_start_kanon
    // 
    // 
    // // Kanon's ability fires: "unless pay 2, discard 2" – must offer pay choice
    test_has_pending_choice(&tg);
    rb_resume_with_choice(&tg.state, 1);
    // 
    int hand_after = tg.state.p[0].hand.n;
    // // LiveCardSet pass draws 1 card; card selection prompt might exist but no discard
    // TODO assert_eq (unresolved): assert_eq!( hand_after, hand_before + 1, "Paying 2 energy should avoid discard (hand {} -> {})", hand_before, hand_after );
    int energy_after = tg.state.p[0].energy_active;
    // TODO assert: assert!( energy_after < 11, "2 energy should be consumed (had 11 after playing kanon, now {})", energy_after );
    // // Consume any remaining choices
    while (test_has_pending_choice(&tg)) rb_resume_with_choice(&tg.state, 0);
    rb_resume_with_choice(&tg.state, -1);
    // TODO: }
    // 
}

