// test_modules/abilities/complex/ability_engine_fixes_test.rs::karin_position_change_removes_not_moved_blade
static void gen_karin_position_change_removes_not_moved_blade(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int energy_after = 0; // auto-fix missing decl
    // 
    int karin = test_id(&tg, "PL!N-pb1-004-R");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    int live_card = test_id(&tg, "PL!-sd1-020-SD");
    // 
    // // inlined helper fill_decks_kari
    // 
    // 
    // // Put a member with cost≤9 at deck index 1 (index 0 gets drawn during phase advance
    // // to LiveCardSetFirstAttacker, exposing our card as the new top for LiveStart reveal).
    int cheap_member = test_id(&tg, "PL!-sd1-010-SD");
    // TODO: tg.state.player1.main_deck.cards.insert(1, cheap_member);
    // 
    test_add_to_hand(&tg, karin);
    test_add_to_hand(&tg, filler);
    test_give_energy(&tg, 20);
    test_play_to_stage(&tg, filler, 0);
    test_play_to_stage(&tg, karin, 1);
    // 
    // // Before LiveStart: Karin has not moved → gets blade 2.
    test_recalc(&tg);
    int blade_before = rb_mods_get_blade(&tg.state.mods, karin);
    CHECK_EQ(blade_before, 2, "karin_position_change_removes_not_moved_blade");
    // 
    // // Record her initial position so we can verify she moved.
    int pos_before = 0;
    CHECK_EQ(pos_before, 1, "karin_position_change_removes_not_moved_blade");
    // 
    // // Advance to LiveStart — fires Karin's ab#1 which reveals top card (cheap_member,
    // // cost≤9 member), moves it to hand, and position-changes Karin.
    // // inlined helper advance_to_live_start_kari
    // 
    // 
    // // Verify: cheap_member was added to hand (not discarded).
    CHECK(test_zone_has_id(&tg, 0, "hand", cheap_member), "karin_position_change_removes_not_moved_blade");
    // 
    // // Verify: Karin moved.
    int pos_after = 0;
    // TODO assert: assert!( pos_after != Some(1), "Karin should have moved from Center after position change" );
    // TODO assert: assert!( pos_after.is_some(), "Karin should still be on stage (not removed)" );
    // 
    // // Verify: after position change, constant ability is re-evaluated and blade is 0.
    int blade_after = rb_mods_get_blade(&tg.state.mods, karin);
    CHECK_EQ(blade_after, 0, "karin_position_change_removes_not_moved_blade");
    // 
    // // Pass through the rest of the Live phase into the next turn.
    // // Sequence: FirstAttackerPerformance → SecondAttackerPerformance →
    // // LiveVictoryDetermination → End → Active (next turn).
    // // During LiveVictoryDetermination, cards_moved_this_turn is cleared.
    // // Next turn's Active phase runs recalculate_constants() → Karin hasn't
    // // moved this turn → not_moved passes again → blade comes back.
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    rb_advance_phase(&tg.state);
    test_recalc(&tg);
    // 
    int blade_next_turn = rb_mods_get_blade(&tg.state.mods, karin);
    CHECK_EQ(blade_next_turn, 2, "karin_position_change_removes_not_moved_blade");
    // 
}

