// test_modules/jidou/complex/card_ability_tests.rs::mirakura_discard_then_draws_count_plus_one
static void gen_mirakura_discard_then_draws_count_plus_one(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    // 
    int ability_card = test_id(&tg, "PL!HS-pb1-003-R");
    int discard_card = test_id(&tg, "PL!HS-pb1-003-R");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    test_add_to_hand(&tg, ability_card);
    test_add_to_hand(&tg, discard_card);
    test_give_energy(&tg, 15);
    // 
    // clear
    // TODO: for (int _i=0; _i<20; _i++) {
    test_add_to_deck(&tg, filler);
    // TODO: }
    // 
    test_play_to_stage(&tg, ability_card, 1);
    // 
    // // Observed chain: the optional same-name discard is NOT auto-paid — it
    // // prompts as an any-number SelectCard ("Select any number of card(s)
    // // from hand"), then re-asks under cap ("Select more card(s) from hand
    // // (or skip to finish)"); the empty answer finalizes.
    test_has_pending_choice(&tg);
    int ct = 0;
    // TODO assert_eq (unresolved): assert_eq!(ct, Some("SelectCard".to_string()));
    rb_resume_with_choice(&tg.state, 0);
    // // Sequential re-prompt: skip to proceed to draw action
    test_has_pending_choice(&tg);
    // TODO assert_eq (unresolved): assert_eq!( tg.pending_choice_type(), Some("SelectCard".to_string()), "expected SelectCard re-ask prompt" );
    rb_resume_with_choice(&tg.state, -1);
    // 
    // // Effect: draw 2 (1 discarded + 1 bonus)
    CHECK(test_zone_has_id(&tg, 0, "discard", discard_card), "mirakura_discard_then_draws_count_plus_one");
    CHECK_EQ(tg.state.p[0].hand.n, 2, "mirakura_discard_then_draws_count_plus_one");
    CHECK_EQ(tg.state.p[0].deck.n, 18, "mirakura_discard_then_draws_count_plus_one");
    // 
}

