// test_modules/integration/gameplay_test.rs::nico_q168_both_appear_from_discard
static void gen_nico_q168_both_appear_from_discard(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int nico = test_id(&tg, "PL!-pb1-018-R");
    int cheap_p1 = test_id(&tg, "PL!SP-sd1-019-SD");
    int cheap_p2 = test_id(&tg, "PL!SP-sd1-020-SD");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    test_add_to_hand(&tg, nico);
    test_add_to_hand(&tg, filler);
    test_add_to_discard(&tg, cheap_p1);
    test_add_to_discard(&tg, cheap_p2);
    test_give_energy(&tg, 7);
    tg.state.p[0].stage[0] = -1;
    // 
    // // Play Nico → both-target debut triggers.
    // // Each player has exactly 1 eligible card in discard → Exact path (no SelectCard).
    // // P1 stage: [nico, -, -] → 2 empty slots → MoveCardsPosition prompt (SelectPosition).
    test_play_to_stage(&tg, nico, 0);
    // 
    // // P1 gets position choice for their own member — choice_player_id stays None (self)
    // TODO assert_eq (unresolved): assert_eq!( tg.pending_choice_type(), Some("SelectPosition".to_string()), "P1 should get position choice" );
    // TODO assert_eq (unresolved): assert_eq!( tg.state .ability_queue .current_entry() .and_then(|e| e.choice_player_id.as_deref()), Some("p1"), "P1's own position choice should have choice_player_id=p1" );
    rb_resume_with_choice(&tg.state, 1);
    // 
    // // Opponent's effect runs inside finalize_choice, creating P2's MoveCardsPosition
    // TODO assert_eq (unresolved): assert_eq!( tg.pending_choice_type(), Some("SelectPosition".to_string()), "P2 should get position choice" );
    // TODO assert_eq (unresolved): assert_eq!( tg.state .ability_queue .current_entry() .and_then(|e| e.choice_player_id.as_deref()), Some("p2"), "P2's position choice should have choice_player_id=p2" );
    rb_resume_with_choice(&tg.state, 2);
    // 
    test_has_pending_choice(&tg);
    // 
    // // P1: Nico at left, cheap_p1 at center
    CHECK_EQ(tg.state.p[0].stage[0], nico, "nico_q168_both_appear_from_discard");
    CHECK_EQ(tg.state.p[0].stage[1], cheap_p1, "nico_q168_both_appear_from_discard");
    CHECK_EQ(tg.state.p[0].stage[2], -1, "nico_q168_both_appear_from_discard");
    // 
    // // P2: cheap_p2 at right
    CHECK_EQ(tg.state.p[1].stage[0], -1, "nico_q168_both_appear_from_discard");
    CHECK_EQ(tg.state.p[1].stage[1], -1, "nico_q168_both_appear_from_discard");
    CHECK_EQ(tg.state.p[1].stage[2], cheap_p2, "nico_q168_both_appear_from_discard");
    // 
    // // Both in wait state
    // TODO assert_eq (unresolved): assert_eq!( tg.state.mods.get_orientation_modifier(cheap_p1), Some("wait"), "P1's member wait state" );
    // TODO assert_eq (unresolved): assert_eq!( tg.state.mods.get_orientation_modifier(cheap_p2), Some("wait"), "P2's member wait state" );
    // 
    // // Cards removed from discard, NOT in hand
    CHECK((!test_zone_has_id(&tg, 0, "discard", cheap_p1)), "nico_q168_both_appear_from_discard");
    CHECK((!test_zone_has_id(&tg, 1, "discard", cheap_p2)), "nico_q168_both_appear_from_discard");
    CHECK((!test_zone_has_id(&tg, 0, "hand", cheap_p1)), "nico_q168_both_appear_from_discard");
    CHECK((!test_zone_has_id(&tg, 1, "hand", cheap_p2)), "nico_q168_both_appear_from_discard");
    // 
}

