// test_modules/integration/gameplay_test.rs::nico_sync_path_opponent_gets_choice_when_self_has_none
static void gen_nico_sync_path_opponent_gets_choice_when_self_has_none(void){
    // 
    // db loaded via rb_load
    TestGame tg; test_game_new(&tg);
    int nico = test_id(&tg, "PL!-pb1-018-R");
    int cheap_a = test_id(&tg, "PL!SP-sd1-019-SD");
    int cheap_b = test_id(&tg, "PL!SP-sd1-020-SD");
    int filler = test_id(&tg, "PL!-sd1-010-SD");
    // 
    // // P1 has NO matching cards in discard (only filler)
    test_add_to_hand(&tg, nico);
    test_add_to_hand(&tg, filler);
    test_add_to_discard(&tg, filler);
    // // P2 has 2 eligible cards → should get SelectCard prompt
    test_add_to_discard(&tg, cheap_a);
    test_add_to_discard(&tg, cheap_b);
    // 
    test_give_energy(&tg, 7);
    tg.state.p[0].stage[0] = -1;
    test_play_to_stage(&tg, nico, 0);
    // 
    // // P1 has 0 matching cards → no choice created for self
    // // Sync path: opponent effect runs directly (handle_both_targets sync path)
    // // Before the fix, spawn_context.target stayed "self" → choice went to P1.
    // // After the fix, spawn_context.target = "opponent" → choice goes to P2.
    // TODO assert_eq (unresolved): assert_eq!( tg.pending_choice_type(), Some("SelectCard".to_string()), "P2 gets SelectCard prompt (P1 had no valid cards)" );
    // TODO assert_eq (unresolved): assert_eq!( tg.state .ability_queue .current_entry() .and_then(|e| e.choice_player_id.as_deref()), Some("p2"), "P2's SelectCard should have choice_player_id=p2 (sync path)" );
    // 
    // // Verify the selection shows P2's discard cards, not P1's
    int actions = 0;
    int select_actions = 0;
    // TODO assert_eq (unresolved): assert_eq!( select_actions.len(), 2, "P2 should see 2 selectable cards from their discard" );
    // 
    rb_resume_with_choice(&tg.state, 0);
    // 
    // // P2 then gets position choice for placing on their stage
    // TODO assert_eq (unresolved): assert_eq!( tg.pending_choice_type(), Some("SelectPosition".to_string()), "P2 gets position choice after selecting card" );
    // TODO assert_eq (unresolved): assert_eq!( tg.state .ability_queue .current_entry() .and_then(|e| e.choice_player_id.as_deref()), Some("p2"), "P2's position choice should have choice_player_id=p2" );
    rb_resume_with_choice(&tg.state, 0);
    // 
    test_has_pending_choice(&tg);
    // 
    // // P1 stage unchanged: Nico at left
    CHECK_EQ(tg.state.p[0].stage[0], nico, "nico_sync_path_opponent_gets_choice_when_self_has_none");
    CHECK_EQ(tg.state.p[0].stage[1], -1, "nico_sync_path_opponent_gets_choice_when_self_has_none");
    CHECK_EQ(tg.state.p[0].stage[2], -1, "nico_sync_path_opponent_gets_choice_when_self_has_none");
    // 
    // // P2's card on stage
    // TODO assert: assert!(tg.state.player2.stage.stage.contains(&cheap_a));
    // TODO assert_eq (unresolved): assert_eq!( tg.state.mods.get_orientation_modifier(cheap_a), Some("wait") );
    // 
    // // cheap_b still in P2 discard (was not selected)
    CHECK(test_zone_has_id(&tg, 1, "discard", cheap_b), "nico_sync_path_opponent_gets_choice_when_self_has_none");
    // 
}

